import CryptoKit
import ExpoModulesCore
import WebKit

/// Content blocker for iOS (ADR-051): WebKit compiles the bundled content blocker lists
/// (`Blocklists/webkit-<n>.json`, generated by `scripts/build-blocklists.mjs`) with
/// `WKContentRuleListStore`, and they are added to the `WKUserContentController` of every
/// react-native-webview.
///
/// react-native-webview does not expose its configuration. A one-line patch
/// (`patches/react-native-webview+<version>.patch`) posts `RNCWebViewDidCreateUserContentController`
/// right after it creates the controller, before the first load: this module listens, keeps a weak
/// list of the controllers, and adds the current lists to each. The patch does not depend on this
/// module (no import): without the module, nobody listens.
///
/// Per-site allowlist ("Bouclier" off): an `ignore-previous-rules` rule for those domains is appended
/// to each list (it only reaches rules of its own list), so a change recompiles the lists; compiled
/// lists are cached by WebKit under an identifier made of the lists' hash and the allowlist.
/// WebKit gives no callback for blocked loads: there are no counters on iOS.
public final class ContentBlockerModule: Module {
  public func definition() -> ModuleDefinition {
    Name("ContentBlocker")

    Constant("counts") { false }

    OnCreate {
      ContentBlockerRegistry.shared.start()
    }

    AsyncFunction("apply") { (enabled: Bool, allowlist: [String], promise: Promise) in
      ContentBlockerRegistry.shared.apply(enabled: enabled, allowlist: allowlist) { result in
        switch result {
        case .success(let count): promise.resolve(count)
        case .failure(let error): promise.reject("ERR_CONTENT_BLOCKER", error.localizedDescription)
        }
      }
    }
    .runOnQueue(.main)
  }
}

final class ContentBlockerRegistry {
  static let shared = ContentBlockerRegistry()
  static let notification = Notification.Name("RNCWebViewDidCreateUserContentController")
  private static let prefix = "browser-blocker-"
  private static let defaultsKey = "browser.contentBlocker.lastConfig"

  private var controllers = NSHashTable<WKUserContentController>.weakObjects()
  private var current: [WKContentRuleList] = []
  private var generation = 0
  private var started = false

  /// Main thread only (notifications are posted from the WebView's creation, on the main thread).
  func start() {
    DispatchQueue.main.async {
      guard !self.started else { return }
      self.started = true
      NotificationCenter.default.addObserver(forName: Self.notification, object: nil, queue: nil) { [weak self] note in
        guard let self, let controller = note.object as? WKUserContentController else { return }
        self.controllers.add(controller)
        for list in self.current { controller.add(list) }
      }
      // Apply the last configuration right away (lists are usually cached): tabs restored at
      // launch get the rules before JavaScript has even started.
      if let last = UserDefaults.standard.dictionary(forKey: Self.defaultsKey),
         let enabled = last["enabled"] as? Bool, let allowlist = last["allowlist"] as? [String] {
        self.apply(enabled: enabled, allowlist: allowlist) { _ in }
      }
    }
  }

  func apply(enabled: Bool, allowlist: [String], completion: @escaping (Result<Int, Error>) -> Void) {
    dispatchPrecondition(condition: .onQueue(.main))
    UserDefaults.standard.set(["enabled": enabled, "allowlist": allowlist], forKey: Self.defaultsKey)
    generation += 1
    let token = generation
    guard enabled else {
      install([], token: token)
      completion(.success(0))
      return
    }
    guard let store = WKContentRuleListStore.default() else {
      completion(.failure(ContentBlockerError("WKContentRuleListStore unavailable")))
      return
    }
    let files = Self.bundledLists()
    let sites = allowlist.filter { $0.range(of: "^[a-z0-9.-]+$", options: .regularExpression) != nil }.sorted()
    let allowRule = sites.isEmpty ? nil :
      "{\"trigger\":{\"url-filter\":\".*\",\"if-domain\":[\(sites.map { "\"*\($0)\"" }.joined(separator: ","))]},\"action\":{\"type\":\"ignore-previous-rules\"}}"
    var compiled: [WKContentRuleList] = []
    var identifiers: Set<String> = []
    let group = DispatchGroup()
    for (index, url) in files.enumerated() {
      guard var json = try? String(contentsOf: url, encoding: .utf8) else { continue }
      if let allowRule, json.hasSuffix("]") {
        json.removeLast()
        json += (json.hasSuffix("[") ? "" : ",") + allowRule + "]"
      }
      let identifier = Self.prefix + "\(index)-" + Self.digest(json)
      identifiers.insert(identifier)
      group.enter()
      store.lookUpContentRuleList(forIdentifier: identifier) { found, _ in
        if let found {
          compiled.append(found)
          group.leave()
          return
        }
        store.compileContentRuleList(forIdentifier: identifier, encodedContentRuleList: json) { list, error in
          if let list { compiled.append(list) } else if let error { NSLog("[ContentBlocker] %@: %@", url.lastPathComponent, error.localizedDescription) }
          group.leave()
        }
      }
    }
    group.notify(queue: .main) {
      guard token == self.generation else { return completion(.success(0)) }
      self.install(compiled, token: token)
      self.removeStale(store: store, keep: identifiers)
      completion(.success(compiled.count))
    }
  }

  private func install(_ lists: [WKContentRuleList], token: Int) {
    guard token == generation else { return }
    for controller in controllers.allObjects {
      for list in current { controller.remove(list) }
      for list in lists { controller.add(list) }
    }
    current = lists
  }

  /// Compiled lists of older builds or allowlists are dropped from the store.
  private func removeStale(store: WKContentRuleListStore, keep: Set<String>) {
    store.getAvailableContentRuleListIdentifiers { identifiers in
      for identifier in identifiers ?? [] where identifier.hasPrefix(Self.prefix) && !keep.contains(identifier) {
        store.removeContentRuleList(forIdentifier: identifier) { _ in }
      }
    }
  }

  private static func bundledLists() -> [URL] {
    let bundle = Bundle(for: ContentBlockerModule.self)
    guard let url = bundle.url(forResource: "ContentBlockerLists", withExtension: "bundle"), let lists = Bundle(url: url) else { return [] }
    return (lists.urls(forResourcesWithExtension: "json", subdirectory: nil) ?? [])
      .filter { $0.lastPathComponent.hasPrefix("webkit-") }
      .sorted { $0.lastPathComponent.localizedStandardCompare($1.lastPathComponent) == .orderedAscending }
  }

  private static func digest(_ text: String) -> String {
    SHA256.hash(data: Data(text.utf8)).prefix(8).map { String(format: "%02x", $0) }.joined()
  }
}

struct ContentBlockerError: LocalizedError {
  let message: String
  init(_ message: String) { self.message = message }
  var errorDescription: String? { message }
}
